<script setup lang="ts">
import { ref } from 'vue'
import type { RecognitionResult } from '../api/review'
import { qualityText } from '../api/review'
defineProps<{ result: RecognitionResult; fileId: string; imageNumber?: number; source?: boolean }>()
const active = ref('')
function points(polygon: number[][]) { return polygon.map(point => point.join(',')).join(' ') }
</script>
<template><section class="ocr-evidence"><p v-if="!source" class="muted">OCR辅助识别可能漏字或误识别，未识别/未匹配均不证明无复用。</p><div v-if="result.originalWidth && result.originalHeight" class="ocr-image"><svg :viewBox="`0 0 ${result.originalWidth} ${result.originalHeight}`" role="img" :aria-label="`配图${imageNumber ?? ''} OCR识别区域`"><image :href="`/api/files/${fileId}`" :width="result.originalWidth" :height="result.originalHeight" /><polygon v-for="line in result.recognitionLines ?? []" :key="line.lineId" :points="points(line.polygon)" :class="{ selected: active === line.lineId }"><title>{{ line.text }}</title></polygon></svg></div><el-alert v-if="result.ocrStatus === 'EMPTY' || (result.ocrStatus && !result.recognitionLines?.length)" title="未识别到文字，未进行文字检索；不能据此判断无复用。" type="warning" :closable="false" /><el-alert v-if="result.textSearchStatus === 'FAILED'" :title="`识别结果已保留，文字检索失败：${result.textSearchErrorCode || '请重试'}`" type="error" :closable="false" /><el-table v-if="result.recognitionLines?.length" :data="result.recognitionLines" size="small" @row-mouse-enter="(row: {lineId: string}) => active = row.lineId" @row-mouse-leave="active = ''"><el-table-column prop="text" label="识别文字" min-width="180" /><el-table-column label="识别置信度" width="110"><template #default="{row}">{{ row.confidence.toFixed(3) }}<span v-if="result.lowConfidenceLineIds?.includes(row.lineId)" class="unsaved"> 低</span></template></el-table-column></el-table><p v-if="result.qualityFlags?.length" class="muted">质量标记：{{ qualityText(result.qualityFlags) }}</p><p v-if="!source">文字检索：{{ result.textSearchStatus === 'COMPLETED' ? '已完成' : result.textSearchStatus === 'FAILED' ? '失败' : '未运行' }}</p></section></template>
